def solve(grid, start, goal):
    rows = len(grid)
    cols = len(grid[0]) if rows > 0 else 0

    def is_valid(r, c):
        return 0 <= r < rows and 0 <= c < cols and grid[r][c] == '.'

    def dfs(r, c, depth, path, visited):
        if (r, c) == goal:
            return path + [(r, c)]
        if depth <= 0:
            return None
        visited.add((r, c))
        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nr, nc = r + dr, c + dc
            if is_valid(nr, nc) and (nr, nc) not in visited:
                result = dfs(nr, nc, depth - 1, path + [(r, c)], visited)
                if result:
                    return result
        visited.remove((r, c))
        return None

    if not is_valid(*start) or not is_valid(*goal):
        return []
    if start == goal:
        return [start]

    max_depth = 2 * max(rows, cols)
    for depth in range(1, max_depth + 1):
        visited = set()
        result = dfs(start[0], start[1], depth, [], visited)
        if result:
            return result
    return []

