from heapq import heappush, heappop

def solve(grid, start, goal):
    if start == goal:
        return [start]

    rows, cols = len(grid), len(grid[0])
    start_row, start_col = start
    goal_row, goal_col = goal

    if grid[start_row][start_col] == '#' or grid[goal_row][goal_col] == '#':
        return []

    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    class Node:
        def __init__(self, pos, g, parent):
            self.pos = pos
            self.g = g
            self.parent = parent

        def __lt__(self, other):
            return self.g < other.g

    open_set = []
    closed_set = set()
    start_node = Node(start, 0, None)
    heappush(open_set, start_node)

    while open_set:
        current_node = heappop(open_set)
        current_pos = current_node.pos
        if current_pos in closed_set:
            continue
        closed_set.add(current_pos)

        if current_pos == goal:
            path = []
            while current_node:
                path.append(current_node.pos)
                current_node = current_node.parent
            return path[::-1]

        for dr, dc in directions:
            r, c = current_pos[0] + dr, current_pos[1] + dc
            if 0 <= r < rows and 0 <= c < cols and grid[r][c] == '.' and (r, c) not in closed_set:
                new_g = current_node.g + 1
                new_node = Node((r, c), new_g, current_node)
                heappush(open_set, new_node)

    return []

