        return [start]

    def is_free(r, c):
        return 0 <= r < rows and 0 <= c < cols and grid[r][c] == '.'

    def get_jump_points(r, c, direction):
        dr, dc = direction
        jump_points = []
        while True:
            r += dr
            c += dc
            if not is_free(r, c):
                break
            jump_points.append((r, c))
        return jump_points

    def get_jump_directions(r, c):
        directions = []
        if is_free(r, c - 1):
            directions.append((-1, 0))
        if is_free(r, c + 1):
            directions.append((1, 0))
        if is_free(r - 1, c):
            directions.append((0, -1))
        if is_free(r + 1, c):
            directions.append((0, 1))
        return directions

    def jump_search(r, c, visited):
        if (r, c) == goal:
            return [(r, c)]
        queue = deque([(r, c, [ (r, c) ])])
        visited.add((r, c))
        while queue:
            curr_r, curr_c, path = queue.popleft()
            for dr, dc in get_jump_directions(curr_r, curr_c):
                jump_points = get_jump_points(curr_r, curr_c, (dr, dc))
                for jump_r, jump_c in jump_points:
