import heapq

def solve(grid, start, goal):
    if start == goal:
        return [start]

    rows, cols = len(grid), len(grid[0])

    def is_valid(r, c):
        return 0 <= r < rows and 0 <= c < cols and grid[r][c] == '.'

    def heuristic(pos, target):
        return abs(pos[0] - target[0]) + abs(pos[1] - target[1])

    class Node:
        def __init__(self, pos, g, parent):
            self.pos = pos
            self.g = g
            self.parent = parent

        def __lt__(self, other):
            return self.g < other.g

    def a_star(start, goal, is_forward):
        open_set = []
        heapq.heappush(open_set, Node(start, 0, None))
        came_from = {}
        g_score = {start: 0}

        while open_set:
            current = heapq.heappop(open_set)
            current_pos = current.pos

            if current_pos == goal:
                path = []
                while current:
                    path.append(current.pos)
                    current = current.parent
                return path[::-1]

            for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                nr, nc = current_pos[0] + dr, current_pos[1] + dc
                if is_valid(nr, nc):
                    tentative_g = current.g + 1
                    if (nr, nc) not in g_score or tentative_g < g_score[(nr, nc)]:
                        g_score[(nr, nc)] = tentative_g
                        heapq.heappush(open_set, Node((nr, nc), tentative_g, current))
                        came_from[(nr, nc)] = current_pos

        return []

    forward_path = a_star(start, goal, True)
    if forward_path:
        return forward_path

    reverse_path = a_star(goal, start, False)
    if reverse_path:
        return reverse_path[::-1]

    return []

