from heapq import heappush, heappop

def solve(grid, start, goal):
    rows, cols = len(grid), len(grid[0])

    # Check if start or goal is a wall or out of bounds
    if not (0 <= start[0] < rows and 0 <= start[1] < cols and grid[start[0]][start[1]] == '.'):
        return []
    if not (0 <= goal[0] < rows and 0 <= goal[1] < cols and grid[goal[0]][goal[1]] == '.'):
        return []

    if start == goal:
        return [start]

    # Directions: up, down, left, right
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    # Jump Point Search
    def jump_search():
        open_set = [(0, start[0], start[1])]
        came_from = {}
        g_cost = {start: 0}

        while open_set:
            _, r, c = heappop(open_set)

            if (r, c) == goal:
                # Reconstruct path
                path = [goal]
                while path[-1] != start:
                    path.append(came_from[path[-1]])
                return path[::-1]

            for dr, dc in directions:
                nr, nc = r + dr, c + dc
                if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] == '.':
                    # Check if the neighbor is a jump point
                    if (dr, dc) == (0, 1) or (dr, dc) == (0, -1):
                        if grid[nr][nc] == '.':
                            if (nr, nc) not in g_cost or g_cost[(r, c)] + 1 < g_cost[(nr, nc)]:
                                g_cost[(nr, nc)] = g_cost[(r, c)] + 1
                                came_from[(nr, nc)] = (r, c)
                                heappush(open_set, (g_cost[(nr, nc)], nr, nc))
                    elif (dr, dc) == (1, 0) or (dr, dc) == (-1, 0):
                        # Check for blocking walls
                        if grid[nr][nc] == '.':
                            if (nr, nc) not in g_cost or g_cost[(r, c)] + 1 < g_cost[(nr, nc)]:
                                g_cost[(nr, nc)] = g_cost[(r, c)] + 1
                                came_from[(nr, nc)] = (r, c)
                                heappush(open_set, (g_cost[(nr, nc)], nr, nc))

        return []

    path = jump_search()
    return path if path else []

