def solve(grid, start, goal):
    def is_valid(pos):
        r, c = pos
        return 0 <= r < len(grid) and 0 <= c < len(grid[0]) and grid[r][c] == '.'

    def dfs(current, path, visited, depth_limit):
        if current == goal:
            return path + [current]
        if depth_limit <= 0:
            return None
        visited.add(current)
        directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]
        for dr, dc in directions:
            next_pos = (current[0] + dr, current[1] + dc)
            if next_pos not in visited and is_valid(next_pos):
                result = dfs(next_pos, path + [current], visited, depth_limit - 1)
                if result:
                    return result
        return None

    if not is_valid(start) or not is_valid(goal):
        return []
    if start == goal:
        return [start]

    max_depth = 2 * max(len(grid), len(grid[0])) + 1
    for depth in range(1, max_depth):
        visited = set()
        result = dfs(start, [], visited, depth)
        if result:
            return result
    return []

