from collections import deque

def solve(grid, start, goal):
    if not (0 <= start[0] < len(grid) and 0 <= start[1] < len(grid[0]) or
            0 <= goal[0] < len(grid) and 0 <= goal[1] < len(grid[0])):
        return []
    if grid[start[0]][start[1]] == '#' or grid[goal[0]][goal[1]] == '#':
        return []
    if start == goal:
        return [start]

    rows, cols = len(grid), len(grid[0])
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    def manhattan(p1, p2):
        return abs(p1[0] - p2[0]) + abs(p1[1] - p2[1])

    def is_free(p):
        r, c = p
        return 0 <= r < rows and 0 <= c < cols and grid[r][c] == '.'

    def dfs_bound(current, path, g, bound, visited):
        if current == goal:
            return path + [current]
        if g + manhattan(current, goal) > bound:
            return None
        for dr, dc in directions:
            nr, nc = current[0] + dr, current[1] + dc
            if is_free((nr, nc)) and (nr, nc) not in visited:
                new_g = g + 1
                new_visited = visited | {(nr, nc)}
                result = dfs_bound((nr, nc), path + [current], new_g, bound, new_visited)
                if result is not None:
                    return result
        return None

    def solve_with_bound(b):
        visited = {start}
        return dfs_bound(start, [], 0, b, visited)

    def get_initial_bound():
        return manhattan(start, goal)

    bound = get_initial_bound()
    while True:
        result = solve_with_bound(bound)
        if result is not None:
            return result
        if bound > manhattan(start, goal):
            return []
        bound += 1

