from collections import deque

def solve(grid, start, goal):
    if not (0 <= start[0] < len(grid) and 0 <= start[1] < len(grid[0])):
        return []
    if not (0 <= goal[0] < len(grid) and 0 <= goal[1] < len(grid[0])):
        return []
    if grid[start[0]][start[1]] == '#' or grid[goal[0]][goal[1]] == '#':
        return []
    if start == goal:
        return [start]

    def manhattan(p1, p2):
        return abs(p1[0] - p2[0]) + abs(p1[1] - p2[1])

    def is_wall(p):
        return grid[p[0]][p[1]] == '#'

    def is_valid(p):
        return 0 <= p[0] < len(grid) and 0 <= p[1] < len(grid[0]) and not is_wall(p)

    def get_neighbors(p):
        directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]
        return [tuple(map(sum, zip(p, d))) for d in directions if is_valid(tuple(map(sum, zip(p, d)]))]

    def ida_star(start, goal):
        def dfs(node, g, bound, path, visited):
            f = g + manhattan(node, goal)
            if f > bound:
                return f, None
            if node == goal:
                return f, path + [node]
            min_bound = float('inf')
            for neighbor in get_neighbors(node):
                if neighbor not in visited:
                    visited.add(neighbor)
                    new_bound, result = dfs(neighbor, g + 1, bound, path + [node], visited)
                    if result is not None:
                        return f, result
                    if new_bound < min_bound:
                        min_bound = new_bound
                    visited.remove(neighbor)
            return min_bound, None

        bound = manhattan(start, goal)
        while True:
            visited = set([start])
            result, _ = dfs(start, 0, bound, [start], visited)
            if result is not None:
                return result
            if result == float('inf'):
                return []
            bound = result

    path = ida_star(start, goal)
    return path

