        while True:
            result = search(start, 0, bound, set())
            if result == 'FOUND':
                return path
            elif result == 'FAIL':
                return []
            else:
                bound = result

    def search(pos, g, bound, visited):
        nonlocal path
        f = g + manhattan_distance(pos, goal)
        if f > bound:
            return f
        if pos == goal:
            path = [pos]
            return 'FOUND'
        visited.add(pos)
        min_new_bound = float('inf')
        for neighbor in get_neighbors(*pos):
            if neighbor not in visited:
                new_g = g + 1
                result = search(neighbor, new_g, bound, visited)
                if result == 'FOUND':
                    path.append(neighbor)
                    return 'FOUND'
                if isinstance(result, int):
