from collections import deque

def solve(grid, start, goal):
    rows = len(grid)
    cols = len(grid[0]) if rows else 0

    if not (0 <= start[0] < rows and 0 <= start[1] < cols):
        return []
    if not (0 <= goal[0] < rows and 0 <= goal[1] < cols):
        return []
    if grid[start[0]][start[1]] == '#' or grid[goal[0]][goal[1]] == '#':
        return []

    if start == goal:
        return [start]

    # Directions: up, down, left, right
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    def is_free(r, c):
        return 0 <= r < rows and 0 <= c < cols and grid[r][c] == '.'

    def jump_point_search(start, goal):
        open_list = deque()
        open_list.append((start[0], start[1], None, None))  # (row, col, previous direction, came_from)
        came_from = {}
        visited = set()
        visited.add((start[0], start[1]))
        found = False
        result = []

        while open_list:
            r, c, prev_dir, came_from_dir = open_list.popleft()
            if (r, c) == goal:
                found = True
                break
            for dr, dc in directions:
                nr, nc = r + dr, c + dc
                if is_free(nr, nc):
                    if (nr, nc) not in visited:
                        visited.add((nr, nc))
                        open_list.append((nr, nc, (dr, dc), (r, c)))
                    # Check if we need to add a jump point
                    if (dr, dc) != prev_dir and (nr, nc) != goal:
                        # Check for turning points
                        step = 1
                        while True:
                            nr2 = r + dr * step
                            nc2 = c + dc * step
                            if not is_free(nr2, nc2):
                                break
                            if (nr2, nc2) == goal:
                                open_list.append((nr2, nc2, (dr, dc), (r, c)))
                                break
                            step += 1
        if not found:
            return []

        # Reconstruct path
        path = [goal]
        current = goal
        while current != start:
            current = came_from.get(current, None)
            if current is None:
                return []
            path.append(current)
        return path[::-1]

    path = jump_point_search(start, goal)
    if path:
        return path
    return []

