from heapq import heappush, heappop

def solve(grid, start, goal):
    rows = len(grid)
    cols = len(grid[0]) if rows else 0

    if not (0 <= start[0] < rows and 0 <= start[1] < cols):
        return []
    if not (0 <= goal[0] < rows and 0 <= goal[1] < cols):
        return []
    if grid[start[0]][start[1]] == '#' or grid[goal[0]][goal[1]] == '#':
        return []
    if start == goal:
        return [start]

    dirs = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    def is_free(r, c):
        return 0 <= r < rows and 0 <= c < cols and grid[r][c] == '.'

    def jump_point_search():
        open_list = [(0, start)]
        came_from = {}
        g_cost = {start: 0}
        found = False
        while open_list:
            _, current = heappop(open_list)
            if current == goal:
                found = True
                break
            for d in dirs:
                next_cell = (current[0] + d[0], current[1] + d[1])
                if not is_free(*next_cell):
                    continue
                next_cell = jump(current, d, grid, rows, cols)
                if next_cell is not None and is_free(*next_cell):
                    tentative_g = g_cost[current] + 1
                    if next_cell not in g_cost or tentative_g < g_cost.get(next_cell, float('inf')):
                        g_cost[next_cell] = tentative_g
                        heappush(open_list, (tentative_g, next_cell))
                        came_from[next_cell] = current
        if not found:
            return []
        path = []
        current = goal
        while current != start:
            path.append(current)
            current = came_from[current]
        path.append(start)
        return path[::-1]

    def jump(current, direction, grid, rows, cols):
        r, c = current
        dr, dc = direction
        while True:
            r += dr
            c += dc
            if not is_free(r, c):
                return (r - dr, c - dc)
            if (r + dr, c + dc) == current:
                return None
        return None

    path = jump_point_search()
    return path if path else []

