import heapq

def solve(grid, start, goal):
    if not grid or start == goal:
        if grid[start[0]][start[1]] == '.':
            return [start]
        else:
            return []

    rows, cols = len(grid), len(grid[0])
    if grid[start[0]][start[1]] == '#' or grid[goal[0]][goal[1]] == '#':
        return []

    def heuristic(pos, target):
        return abs(pos[0] - target[0]) + abs(pos[1] - target[1])

    def get_neighbors(pos):
        r, c = pos
        for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] == '.':
                yield (nr, nc)

    # Forward search from start
    forward_frontier = [(heuristic(start, goal), 0, start, None)]
    forward_visited = {start: (0, None)}

    # Backward search from goal
    backward_frontier = [(heuristic(goal, start), 0, goal, None)]
    backward_visited = {goal: (0, None)}

    while forward_frontier and backward_frontier:
        # Forward step
        f_cost, f_steps, f_pos, f_prev = heapq.heappop(forward_frontier)
        if f_pos in backward_visited:
            # Paths meet, reconstruct path
            path = []
            current = f_pos
            while current is not None:
                path.append(current)
                current = f_prev
            path.reverse()
            # Add the backward path
            current = f_pos
            while current != goal:
                current = backward_visited[current][1]
                path.append(current)
            return path

        for neighbor in get_neighbors(f_pos):
            new_cost = f_steps + 1
            if neighbor not in forward_visited or new_cost < forward_visited[neighbor][0]:
                forward_visited[neighbor] = (new_cost, f_pos)
                heapq.heappush(forward_frontier, (new_cost + heuristic(neighbor, goal), new_cost, neighbor, f_pos))

        # Backward step
        b_cost, b_steps, b_pos, b_prev = heapq.heappop(backward_frontier)
        if b_pos in forward_visited:
            # Paths meet, reconstruct path
            path = []
            current = b_pos
            while current is not None:
                path.append(current)
                current = b_prev
            path.reverse()
            # Add the forward path
            current = b_pos
            while current != start:
                current = forward_visited[current][1]
                path.append(current)
            return path

        for neighbor in get_neighbors(b_pos):
            new_cost = b_steps + 1
            if neighbor not in backward_visited or new_cost < backward_visited[neighbor][0]:
                backward_visited[neighbor] = (new_cost, b_pos)
                heapq.heappush(backward_frontier, (new_cost + heuristic(neighbor, start), new_cost, neighbor, b_pos))

    return []

