import heapq

def solve(grid, start, goal):
    if grid[start[0]][start[1]] == '#' or grid[goal[0]][goal[1]] == '#':
        return []
    if start == goal:
        return [start]

    rows, cols = len(grid), len(grid[0])
    dirs = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    def heuristic(pos, target):
        return abs(pos[0] - target[0]) + abs(pos[1] - target[1])

    def a_star(start, goal):
        frontier = [(heuristic(start, goal), 0, start, None)]
        visited = set()
        came_from = {}
        while frontier:
            _, cost, current, prev = heapq.heappop(frontier)
            if current in visited:
                continue
            visited.add(current)
            came_from[current] = prev
            if current == goal:
                path = []
                while current:
                    path.append(current)
                    current = came_from.get(current)
                return path[::-1]
            for dx, dy in dirs:
                x, y = current[0] + dx, current[1] + dy
                if 0 <= x < rows and 0 <= y < cols and grid[x][y] == '.' and (x, y) not in visited:
                    new_cost = cost + 1
                    heapq.heappush(frontier, (new_cost + heuristic((x, y), goal), new_cost, (x, y), current))
        return None

    forward_path = a_star(start, goal)
    backward_path = a_star(goal, start)

    if not forward_path or not backward_path:
        return []

    # Find the intersection point
    forward_set = set(forward_path)
    backward_set = set(backward_path)
    intersection = forward_set & backward_set
    if not intersection:
        return []

    intersection = sorted(intersection, key=lambda p: forward_path.index(p))
    meet_point = intersection[0]

    forward_part = forward_path[:forward_path.index(meet_point) + 1]
    backward_part = backward_path[backward_path.index(meet_point):]

    return forward_part + backward_part[1:]

