            visited.add(current)
            came_from[current] = prev
            if current == goal:
                path = []
                while current:
                    path.append(current)
                    current = came_from.get(current)
                return path[::-1]
            for dx, dy in dirs:
                x, y = current[0] + dx, current[1] + dy
                if 0 <= x < rows and 0 <= y < cols and grid[x][y] == '.' and (x, y) not in visited:
