import heapq

def solve(grid, start, goal):
    if start == goal:
        return [start]

    rows, cols = len(grid), len(grid[0])
    start_row, start_col = start
    goal_row, goal_col = goal

    if grid[start_row][start_col] == '#' or grid[goal_row][goal_col] == '#':
        return []

    def heuristic(pos, target):
        return abs(pos[0] - target[0]) + abs(pos[1] - target[1])

    def a_star(start, goal, heuristic):
        frontier = [(heuristic(start, goal), 0, start, None)]
        came_from = {}
        visited = set()
        while frontier:
            _, cost, current, prev = heapq.heappop(frontier)
            if current in visited:
                continue
            visited.add(current)
            came_from[current] = prev
            if current == goal:
                break
            r, c = current
            for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                nr, nc = r + dr, c + dc
                if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] != '#' and (nr, nc) not in visited:
                    new_cost = cost + 1
                    heapq.heappush(frontier, (new_cost + heuristic((nr, nc), goal), new_cost, (nr, nc), current))
        path = []
        current = goal
        while current in came_from:
            path.append(current)
            current = came_from[current]
        path.append(start)
        path.reverse()
        return path

    forward_path = a_star(start, goal, heuristic)
    backward_path = a_star(goal, start, lambda pos, target: heuristic(pos, target))

    for f, b in zip(forward_path, backward_path):
        if f == b:
            idx = forward_path.index(f)
            return forward_path[:idx+1] + backward_path[idx:][::-1]

    return []

