    def get_neighbors(pos):
        r, c = pos
        for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] == '.':
                yield (nr, nc)

    # Bidirectional A* search
    forward_heap = []
    backward_heap = []
    forward_visited = {}
    backward_visited = {}

    heappush(forward_heap, (manhattan(start, goal), 0, start))
    heappush(backward_heap, (manhattan(goal, start), 0, goal))

    forward_visited[start] = (0, None)
    backward_visited[goal] = (0, None)

