        f_cost, f_dist, f_pos = heappop(forward_heap)
        if f_pos in backward_visited:
            # Found a meeting point
            path = []
            curr = f_pos
            while curr is not None:
                path.append(curr)
                curr = forward_visited[curr][1]
            path.reverse()
            curr = f_pos
            while curr is not None:
                path.append(curr)
                curr = backward_visited[curr][1]
            return path

        for neighbor in get_neighbors(f_pos):
            if neighbor not in forward_visited:
                new_dist = f_dist + 1
                heappush(forward_heap, (new_dist + manhattan(neighbor, goal), new_dist, neighbor))
                forward_visited[neighbor] = (new_dist, f_pos)

