                        g_score[neighbor] = tentative_g
                        f_score[neighbor] = tentative_g + abs(neighbor[0] - goal[0]) + abs(neighbor[1] - goal[1])
                        heappush(open_set, (f_score[neighbor], neighbor))
        return None

