                        g_score[(nr, nc)] = tentative_g
                        heapq.heappush(frontier_heap, (g_score[(nr, nc)] + heuristic((nr, nc), goal), tentative_g, (nr, nc)))
        return None

    def manhattan(p, q):
        return abs(p[0] - q[0]) + abs(p[1] - q[1])

