def solve(grid, start, goal):
    if not grid or not start or not goal:
        return []
    rows, cols = len(grid), len(grid[0])
    start_row, start_col = start
    goal_row, goal_col = goal

    if grid[start_row][start_col] == '#' or grid[goal_row][goal_col] == '#':
        return []

    def get_neighbors(r, c):
        neighbors = []
        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] == '.':
                neighbors.append((nr, nc))
        return neighbors

    def a_star(start, goal, heuristic):
        frontier = [(heuristic(start, goal), 0, start)]
        came_from = {}
        cost_so_far = {start: 0}
        visited = set()
        while frontier:
            _, cost, current = heapq.heappop(frontier)
            if current in visited:
                continue
            visited.add(current)
            if current == goal:
                break
            for next in get_neighbors(*current):
                new_cost = cost + 1
                if next not in cost_so_far or new_cost < cost_so_far[next]:
                    cost_so_far[next] = new_cost
                    heapq.heappush(frontier, (new_cost + heuristic(next, goal), new_cost, next))
                    came_from[next] = current
        if goal not in came_from:
            return None
        path = []
        current = goal
        while current != start:
            path.append(current)
            current = came_from[current]
        path.append(start)
        path.reverse()
        return path

    def manhattan(p1, p2):
        return abs(p1[0] - p2[0]) + abs(p1[1] - p2[1])

    if start == goal:
        return [start]

    forward_path = a_star(start, goal, manhattan)
    backward_path = a_star(goal, start, manhattan)

    if not forward_path or not backward_path:
        return []

    forward_set = set(forward_path)
    backward_set = set(backward_path)

    common = forward_set & backward_set
    if not common:
        return []

    for i in range(len(forward_path)):
        if forward_path[i] in common:
            forward_part = forward_path[:i+1]
            break
    else:
        forward_part = forward_path

    for i in range(len(backward_path)):
        if backward_path[i] in common:
            backward_part = backward_path[:i+1]
            break
    else:
        backward_part = backward_path

    backward_part.reverse()
    return forward_part + backward_part[1:]

