import heapq

def solve(grid, start, goal):
    if start == goal:
        return [start]

    rows, cols = len(grid), len(grid[0])
    if grid[start[0]][start[1]] == '#' or grid[goal[0]][goal[1]] == '#':
        return []

    # Directions: up, down, left, right
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    def heuristic(pos, target):
        return abs(pos[0] - target[0]) + abs(pos[1] - target[1])

    # A* search with priority queue
    def a_star(start, goal):
        frontier = [(heuristic(start, goal), 0, start, None)]
        came_from = {}
        visited = set()

        while frontier:
            _, cost, current, prev = heapq.heappop(frontier)
            if current in visited:
                continue
            visited.add(current)
            came_from[current] = prev
            if current == goal:
                path = []
                while current in came_from:
                    path.append(current)
                    current = came_from[current]
                path.append(start)
                path.reverse()
                return path
            for dr, dc in directions:
                r, c = current[0] + dr, current[1] + dc
                if 0 <= r < rows and 0 <= c < cols and grid[r][c] == '.' and (r, c) not in visited:
                    new_cost = cost + 1
                    heapq.heappush(frontier, (new_cost + heuristic((r, c), goal), new_cost, (r, c), current))
        return None

    # Bidirectional A* search
    forward_path = a_star(start, goal)
    backward_path = a_star(goal, start)

    if not forward_path or not backward_path:
        return []

    # Find the meeting point
    forward_set = set(forward_path)
    backward_set = set(backward_path)
    meeting_point = None
    for point in forward_path:
        if point in backward_set:
            meeting_point = point
            break

    if not meeting_point:
        return []

    # Combine the paths
    forward_index = forward_path.index(meeting_point)
    backward_index = backward_path.index(meeting_point)

    return forward_path[:forward_index + 1] + backward_path[backward_index:][::-1]

from heapq import heappush, heappop

def solve(grid, start, goal):
    if grid[start[0]][start[1]] == '#' or grid[goal[0]][goal[1]] == '#':
        return []
    if start == goal:
        return [start]

    rows, cols = len(grid), len(grid[0])
    dirs = [(-1,0),(1,0),(0,-1),(0,1)]

    def heuristic(pos, target):
        return abs(pos[0] - target[0]) + abs(pos[1] - target[1])

    def a_star(start, goal):
        open_set = []
        heappush(open_set, (heuristic(start, goal), 0, start, None))
        came_from = {}
        g_score = {start: 0}
        f_score = {start: heuristic(start, goal)}

        while open_set:
            _, cost, current, prev = heappop(open_set)

            if current == goal:
                path = []
                while current:
                    path.append(current)
                    current = prev
                return path[::-1]

            for dr, dc in dirs:
                r, c = current[0] + dr, current[1] + dc
                if 0 <= r < rows and 0 <= c < cols and grid[r][c] == '.':
                    tentative_g = g_score[current] + 1
                    if (r, c) not in g_score or tentative_g < g_score[(r, c)]:
                        came_from[(r, c)] = current
                        g_score[(r, c)] = tentative_g
                        f_score[(r, c)] = tentative_g + heuristic((r, c), goal)
                        heappush(open_set, (f_score[(r, c)], f_score[(r, c)], (r, c), current))

        return []

    forward_path = a_star(start, goal)
    backward_path = a_star(goal, start)

    if not forward_path or not backward_path:
        return []

    forward_set = set(forward_path)
    backward_set = set(backward_path)
    common = forward_set & backward_set

    if not common:
        return []

    for i in range(len(forward_path)):
        if forward_path[i] in common:
            forward_path = forward_path[:i+1]
            break

    for i in range(len(backward_path)-1, -1, -1):
        if backward_path[i] in common:
            backward_path = backward_path[i:]
            break

    return forward_path + backward_path[1:]

