from collections import deque

def solve(grid, start, goal):
    if start == goal:
        return [start]

    rows, cols = len(grid), len(grid[0])
    if grid[start[0]][start[1]] == '#' or grid[goal[0]][goal[1]] == '#':
        return []

    def is_valid(r, c):
        return 0 <= r < rows and 0 <= c < cols and grid[r][c] == '.'

    def manhattan(p, q):
        return abs(p[0] - q[0]) + abs(p[1] - q[1])

    # Bidirectional A* search
    # Forward from start, backward from goal
    forward = {}
    backward = {}
    forward_visited = set()
    backward_visited = set()

    forward_queue = deque()
    forward_queue.append((start, [start]))
    forward_visited.add(start)
    forward[manhattan(start, goal)] = start

    backward_queue = deque()
    backward_queue.append((goal, [goal]))
    backward_visited.add(goal)
    backward[manhattan(goal, start)] = goal

    while forward_queue and backward_queue:
        # Expand forward
        while forward_queue:
            current, path = forward_queue.popleft()
            for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                r, c = current[0] + dr, current[1] + dc
                if is_valid(r, c) and (r, c) not in forward_visited:
                    forward_visited.add((r, c))
                    new_path = path + [(r, c)]
                    forward[manhattan((r, c), goal)] = (r, c)
                    forward_queue.append(((r, c), new_path))
                    if (r, c) in backward_visited:
                        return new_path
        # Expand backward
        while backward_queue:
            current, path = backward_queue.popleft()
            for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                r, c = current[0] + dr, current[1] + dc
                if is_valid(r, c) and (r, c) not in backward_visited:
                    backward_visited.add((r, c))
                    new_path = path + [(r, c)]
                    backward[manhattan((r, c), start)] = (r, c)
                    backward_queue.append(((r, c), new_path))
                    if (r, c) in forward_visited:
                        return new_path

    return []

