                if neighbor not in visited:
                    new_cost = cost + 1
                    heapq.heappush(frontier, (new_cost + heuristic(neighbor, goal), new_cost, neighbor, current))
        return None

    def manhattan(pos, target):
        return abs(pos[0] - target[0]) + abs(pos[1] - target[1])

