            for neighbor in get_neighbors(*current):
                tentative_g_score = g_score[current] + 1
                if neighbor not in g_score or tentative_g_score < g_score[neighbor]:
                    came_from[neighbor] = current
                    g_score[neighbor] = tentative_g_score
                    heapq.heappush(open_set, (tentative_g_score + heuristic(neighbor, goal), tentative_g_score, neighbor))
        return None

    def manhattan(p1, p2):
        return abs(p1[0] - p2[0]) + abs(p1[1] - p2[1])

    forward_path = a_star(start, goal, manhattan)
    backward_path = a_star(goal, start, manhattan)

    if not forward_path or not backward_path:
        return []

    forward_set = set(forward_path)
    backward_set = set(backward_path)
    intersection = forward_set & backward_set
    if not intersection:
        return []

    for point in forward_path:
        if point in intersection:
            forward_idx = forward_path.index(point)
            break
    else:
        return []

    backward_idx = backward_path.index(point)
    backward_path = backward_path[:backward_idx+1][::-1]

    return forward_path[:forward_idx+1] + backward_path[1:]
